render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(set = cfg$x, size = cfg$y), c("set", "size")); set_values <- as.character(data[[cfg$x]]); size_values <- data[[cfg$y]]; get_size <- function(k) { v <- size_values[set_values == k]; if (length(v)) v[[1]] else 0 }; a <- get_size("A"); b <- get_size("B"); ab <- get_size("AB"); chart_open_device(cfg$outputPath, cfg$format); VennDiagram::draw.pairwise.venn(area1 = a, area2 = b, cross.area = ab, category = c("A", "B"), fill = c(cfg$color %||% "#0A84FF", "#FF6B35"), alpha = c(0.55, 0.55), scaled = FALSE, ind = FALSE, main = cfg$title %||% "集合交集"); grid::grid.newpage(); grDevices::dev.off(); cfg$outputPath }
